#!/usr/bin/env python3
# [AI-GEN] Generated by AI | Model: Claude | Date: 2026-07-22
"""
AI 代码标注检查脚本

检查 AI 生成的代码是否包含 [AI-GEN]  GOVERNANCE.md 规范，所有 AI 生成的函数/类必须添加标注。

用法:
    python check_ai_annotation.py                    # 检查所有 Python 文件
    python check_ai_annotation.py --path tools/      # 检查指定目录
    python check_ai_annotation.py --file test.py     # 检查单个文件
    python check_ai_annotation.py --fix              # 自动添加标注
"""

import argparse
import re
import sys
from pathlib import Path
from typing import Any, TypedDict


class CheckResult(TypedDict):
    file: str
    has_annotation: bool
    issues: list[str]
    passed: bool


# AI 标注模式
AI_ANNOTATION_PATTERN = r"# \[AI-GEN\]"
AI_ANNOTATION_TEMPLATE = "# [AI-GEN] Generated by AI | Model: {model} | Date: {date}"

# 检测 AI 生成代码的启发式模式 (仅匹配独立注释行，非字符串内容)
AI_GENERATION_INDICATORS = [
    r"^\s*#\s*This function (is|was) (generated|created|written) by",
    r"^\s*#\s*AI[- ]generated",
    r"^\s*#\s*Generated with (Claude|GPT|Copilot|AI)",
    r"^\s*#\s*AI assistant",
    r"^\s*#\s*This code (was|is) AI",
]


def has_ai_annotation(content: str) -> bool:
    """检查文件是否包含 AI 标注"""
    return bool(re.search(AI_ANNOTATION_PATTERN, content))


def detect_ai_generated_functions(content: str) -> list[dict[str, Any]]:
    """检测可能的 AI 生成函数 (启发式)"""
    results = []

    # 检测函数定义
    func_pattern = r"^(?:def|function|const\s+\w+\s*=\s*(?:async\s+)?(?:function|\())"
    lines = content.split("\n")

    for i, line in enumerate(lines, 1):
        if re.match(func_pattern, line.strip()):
            # 检查前 5 行是否有 AI 标注
            start = max(0, i - 6)
            context = "\n".join(lines[start:i])
            if not has_ai_annotation(context):
                # 逐行检查是否有 AI 生成指标 (仅匹配独立注释行)
                for context_line in lines[max(0, i - 6) : i]:
                    for indicator in AI_GENERATION_INDICATORS:
                        if re.search(indicator, context_line, re.IGNORECASE):
                            results.append(
                                {
                                    "line": i,
                                    "function": line.strip()[:50],
                                    "reason": "检测到 AI 生成指标但缺少标注",
                                }
                            )
                            break
                    else:
                        continue
                    break

    return results


def check_file(filepath: Path) -> CheckResult:
    """检查单个文件"""
    result: CheckResult = {
        "file": str(filepath),
        "has_annotation": False,
        "issues": [],
        "passed": True,
    }

    if not filepath.exists():
        result["issues"].append(f"文件不存在: {filepath}")
        result["passed"] = False
        return result

    content = filepath.read_text(encoding="utf-8")
    result["has_annotation"] = has_ai_annotation(content)

    # 检测可能的 AI 生成函数
    ai_functions = detect_ai_generated_functions(content)

    for func in ai_functions:
        result["issues"].append(f"Line {func['line']}: {func['function'][:30]}... - {func['reason']}")

    result["passed"] = len(result["issues"]) == 0
    return result


def fix_file(filepath: Path, model: str = "unknown") -> bool:
    """自动添加 AI 标注"""
    content = filepath.read_text(encoding="utf-8")

    if has_ai_annotation(content):
        return False

    from datetime import datetime

    date = datetime.now().strftime("%Y-%m-%d")
    annotation = AI_ANNOTATION_TEMPLATE.format(model=model, date=date)
    new_content = f"{annotation}\n{content}"
    filepath.write_text(new_content, encoding="utf-8")
    return True


def _collect_files(args: argparse.Namespace) -> list[Path]:
    """Collect files to check based on args."""
    files_to_check = []
    if args.file:
        files_to_check = [args.file]
    elif args.path:
        files_to_check = list(args.path.rglob("*.py"))
    else:
        files_to_check = list(Path("tools/scripts").rglob("*.py"))
    return [f for f in files_to_check if "__pycache__" not in str(f)]


def _process_file(filepath: Path, args: argparse.Namespace) -> tuple[str, int]:
    """Process a single file, return (status, fix_applied)."""
    result = check_file(filepath)

    # Failed: 存在未标注的 AI 生成函数
    if not result["passed"]:
        for issue in result["issues"]:
            print(f"   {issue}")

    fix_applied = 0
    if args.fix and not result["has_annotation"]:
        if fix_file(filepath, args.model):
            print(f"   🔧 {filepath.name} - 已自动标注")
            fix_applied = 1

    if result["passed"]:
        if args.strict and not result["has_annotation"]:
            return ("warn", 0)
        return ("pass", fix_applied)
    return ("fail", fix_applied)


def _print_summary(passed: int, warned: int, failed: int) -> None:
    """Print summary and exit."""
    print("\n" + "=" * 60)
    print(f"  结果: {passed} 通过, {warned} 警告, {failed} 失败")
    print("=" * 60)
    sys.exit(1 if failed > 0 else 0)


def main() -> None:
    """主函数"""
    parser = argparse.ArgumentParser(description="检查 AI 代码标注")
    parser.add_argument("--path", type=Path, help="检查指定目录")
    parser.add_argument("--file", type=Path, help="检查单个文件")
    parser.add_argument("--fix", action="store_true", help="自动添加标注")
    parser.add_argument("--model", default="unknown", help="AI 模型名称")
    parser.add_argument("--strict", action="store_true", help="严格模式 (警告未标注)")
    args = parser.parse_args()

    print("=" * 60)
    print("  AI 代码标注检查")
    print("=" * 60)

    files_to_check = _collect_files(args)

    passed = 0
    warned = 0
    failed = 0

    for filepath in sorted(files_to_check):
        status, _ = _process_file(filepath, args)
        if status == "pass":
            print(f"✅ {filepath.name}")
            passed += 1
        elif status == "warn":
            print(f"⚠️  {filepath.name} - 缺少 [AI-GEN] 标注")
            warned += 1
        else:
            print(f"❌ {filepath.name}")
            failed += 1

    _print_summary(passed, warned, failed)


if __name__ == "__main__":
    main()
